/* Ritme service worker.
 *
 * Generated by scripts/generate-version.mjs — do not edit public/sw.js
 * directly; edit scripts/sw.template.js instead. APP_VERSION and BUILD_ID
 * below are stamped on every build, so every deploy (even one that did
 * not bump package.json) ships a byte-different worker: the browser fires
 * `updatefound`, which drives the in-app update toast, refreshes the precache
 * and runs the old-cache cleanup below.
 *
 * Caching policy:
 *  - Precache (per build): offline page, icons, manifest.
 *  - Navigations: network-first (navigation preload + timeout) → offline.html.
 *  - /_next/static/* (content-hashed, immutable): cache-first.
 *  - Other static assets (icons, fonts, images): stale-while-revalidate.
 *  - Runtime cache is capped at RUNTIME_MAX_ENTRIES (oldest evicted first).
 *  - NEVER cached: /api/* (health data — privacy, CLAUDE.md §11), version.json
 *    (update source of truth), sw.js itself, and HTML documents.
 */

const APP_VERSION = '__APP_VERSION__';
const BUILD_ID = '__BUILD_ID__';
const PRECACHE = `ritme-precache-v${APP_VERSION}-${BUILD_ID}`;
// Deliberately NOT per build: hashed chunks keep their names across deploys,
// and keeping the previous build's chunks lets a tab that is still on the old
// HTML finish loading them. The entry cap keeps it bounded instead.
const RUNTIME = 'ritme-runtime-v2';
const RUNTIME_MAX_ENTRIES = 150;
const OFFLINE_URL = '/offline.html';
// A stalled connection (VPN / filtering) must end on the offline page, not a
// blank screen that spins forever.
const NAVIGATION_TIMEOUT_MS = 10000;

const PRECACHE_URLS = [
  OFFLINE_URL,
  '/manifest.webmanifest',
  '/logo.webp',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/maskable-192.png',
  '/icons/maskable-512.png',
  '/icons/apple-touch-icon.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(PRECACHE)
      // `reload` skips the HTTP cache so a new build never precaches a stale copy.
      .then((cache) => cache.addAll(PRECACHE_URLS.map((url) => new Request(url, { cache: 'reload' })))),
  );
  // Do NOT skipWaiting here — activation is user-driven via the update button.
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Every cache that is not this build's precache or the shared runtime
      // cache belongs to an older worker: drop it.
      const keys = await caches.keys();
      await Promise.all(
        keys.filter((key) => key !== PRECACHE && key !== RUNTIME).map((key) => caches.delete(key)),
      );
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable().catch(() => undefined);
      }
      // Claiming makes the first visit controlled (so offline works right away).
      // The page only reloads on controllerchange if it was controlled at load
      // or the user pressed "update" — see shared/pwa/useAppUpdate.ts.
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
  if (event.data?.type === 'CLEAR_RUNTIME_CACHE') {
    event.waitUntil(caches.delete(RUNTIME));
  }
});

function isHashedAsset(url) {
  return url.pathname.startsWith('/_next/static/');
}

function isStaticAsset(url) {
  return (
    url.pathname.startsWith('/icons/') ||
    url.pathname.startsWith('/fonts/') ||
    /\.(?:png|webp|jpg|jpeg|svg|gif|ico|woff2?)$/.test(url.pathname)
  );
}

// Oldest-first eviction: Cache Storage returns keys in insertion order, and a
// re-put moves an entry to the end, so this approximates LRU-by-write.
async function trimRuntimeCache() {
  const cache = await caches.open(RUNTIME);
  const keys = await cache.keys();
  const excess = keys.length - RUNTIME_MAX_ENTRIES;
  if (excess <= 0) return;
  await Promise.all(keys.slice(0, excess).map((key) => cache.delete(key)));
}

async function putRuntime(request, response) {
  if (!response || !response.ok || response.type === 'opaque') return;
  const cache = await caches.open(RUNTIME);
  await cache.put(request, response);
  await trimRuntimeCache();
}

function withTimeout(promise, ms) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('navigation timeout')), ms);
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

async function offlineResponse() {
  const cached = await caches.match(OFFLINE_URL);
  return cached ?? Response.error();
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Bypass entirely: API (health data must never rest in Cache Storage),
  // the version manifest, and the worker itself.
  if (
    url.pathname.startsWith('/api/') ||
    url.pathname === '/version.json' ||
    url.pathname === '/sw.js'
  ) {
    return;
  }

  // Navigations: network-first (never cached), offline fallback.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const network = (async () => (await event.preloadResponse) || fetch(request))();
          return await withTimeout(network, NAVIGATION_TIMEOUT_MS);
        } catch {
          return offlineResponse();
        }
      })(),
    );
    return;
  }

  // Content-hashed build output: the name changes whenever the bytes do, so a
  // cached copy is always correct — cache-first, no background refetch.
  if (isHashedAsset(url)) {
    event.respondWith(
      caches.match(request, { cacheName: RUNTIME }).then((cached) => {
        if (cached) return cached;
        return fetch(request).then((response) => {
          // Clone before handing the body to the page; the waitUntil call
          // happens while respondWith is still pending, which keeps it legal.
          event.waitUntil(putRuntime(request, response.clone()).catch(() => undefined));
          return response;
        });
      }),
    );
    return;
  }

  // Other static assets (unhashed names): stale-while-revalidate.
  if (isStaticAsset(url)) {
    const network = fetch(request).catch(() => undefined);
    // Registered first, so the clone happens before the page reads the body.
    const saved = network
      .then((response) => response && putRuntime(request, response.clone()))
      .catch(() => undefined);
    event.waitUntil(saved);
    event.respondWith(
      caches
        .match(request, { cacheName: RUNTIME })
        .then(async (cached) => cached ?? (await network) ?? Response.error()),
    );
  }
});
